const pdfOffset=(p:number)=>p<=1368?p-1020:p<=1387?p-1036:p-1040;
const q=(n:number,row:SourceRow,score:number,reason:string,expressions:string[],related:number[]=[])=>
 advancedQuestion('nefrologie',36,pdfOffset,`nefrologie-adv-${String(n).padStart(3,'0')}`,row,[score,reason],expressions,undefined,related);

export const NEFROLOGIE_C=[
q(65,['Pielografia anterogradă:',
 ['Implică puncția percutanată a sistemului pielocaliceal și injectarea de contrast până la nivelul obstrucției','Permite amplasarea de tuburi de dren și stenturi în timpul procedurii','Este investigația de primă intenție a refluxului vezico-ureteral la copil, în locul cistouretrografiei','Se realizează prin cateterizarea vezicii și instilarea contrastului, urmată de golire','Are ca principală complicație anevrismul arteriovenos în aproximativ 20% din cazuri'],'AB',1351,'Investigații — Pielografia anterogradă',
 'Recunoașterea căii percutanate a pielografiei anterograde și a posibilității de dren/stent, distincte de cistouretrografie.',
 ['Textul definește pielografia anterogradă prin puncție percutanată a sistemului pielocaliceal și injectare de contrast până la obstrucție.','Pot fi amplasate tuburi de dren și stenturi în timpul procedurii.','Refluxul la copil se studiază prin cistouretrografie, nu prin pielografie anterogradă.','Cateterizarea vezicii definește cistouretrografia.','Anevrismul arteriovenos de ~20% figurează la complicațiile biopsiei, nu ale pielografiei.']],
 8,'Distractorii mută indicația pediatrică a cistouretrografiei și complicația biopsiei pe o investigație de puncție pielocaliceală.',['Pielografia anterogradă','tuburi de dren']),

q(66,['Aortografia sau arteriografia renală (inclusiv DSA):',
 ['Sunt folosite diagnostic și terapeutic în suspiciunea de stenoză de arteră renală','Permit angioplastia cu balon și stentarea ulterioară','Printre complicații se numără embolia cu cristale de colesterol și nefropatia de contrast','Înlocuiesc MAG3 ca test de primă intenție al obstrucției pielocaliceale','Sunt contraindicate în stenoza de arteră renală, fiind rezervate evaluării refluxului vezical'],'ABC',1351,'Investigații — Angiografia renală',
 'Recunoașterea dublului rol diagnostic-terapeutic al DSA și a celor două complicații citate (colesterol, contrast).',
 ['Textul precizează folosirea diagnostică și terapeutică în suspiciunea de stenoză de arteră renală.','Angioplastia cu balon și stentarea ulterioară sunt menționate explicit.','Embolia cu cristale de colesterol și leziunile renale induse de contrast sunt complicațiile citate.','Obstrucția pielocaliceală se evaluează cu MAG3, nu cu arteriografie.','Arteriografia este indicată tocmai în stenoza de arteră renală, nu este contraindicată.']],
 8,'Capcana este confuzia cu MAG3/cistouretrografie; complicațiile reale (colesterol, contrast) trebuie ținute împreună.',['embolia cu cristale de colesterol','angioplastia cu balon']),

q(67,['În timpul biopsiei renale transcutanate (Cadranul 36.6) se cere:',
 ['Pacientul să stea în decubit ventral, cu o pernă tare sub abdomen','Localizarea rinichiului cu ecograful și injectarea de anestezic local pe calea de biopsie','Instrucțiunea ca pacientul să țină respirația când se efectuează biopsia','Mobilizare imediată, fără anestezie, pentru a scurta durata procedurii','Poziție în decubit dorsal, cu perna sub ceafă, ca la biopsia hepatică'],'ABC',1352,'Glomerulul și afectarea glomerulară — Biopsia: timpul procedurii',
 'Aplicarea pașilor intra-procedurali din Cadranul 36.6 (decubit ventral, ecograf, apnee).',
 ['Cadranul cere decubit ventral cu pernă tare sub abdomen.','Localizarea ecografică și anestezicul local pe traiect sunt explicitate.','Pacientul este instruit să țină respirația în momentul biopsiei.','Mobilizarea imediată și absența anesteziei contrazic cadranul.','Decubitul dorsal este al altor puncții; aici poziția este ventrală.']],
 8,'Inversează poziția (ventral versus dorsal) și cerința de apnee, două detalii consecutive din același cadran.',['decubit ventral','țină respiraţia']),

q(68,['Afecțiunile glomerulare, ca și cauză de boală renală în stadiu terminal:',
 ['Reprezintă a treia cea mai frecventă cauză, după diabet și hipertensiune, în Europa și SUA','Acoperă aproximativ 10–15% din cazurile de BAT','Sunt prima cauză de BAT, depășind diabetul în Occident','Interesează un singur rinichi, celălalt fiind de regulă cruțat','Nu asociază leziune interstițială, afectarea fiind strict glomerulară'],'AB',1352,'Glomerulul și afectarea glomerulară — Epidemiologie și trăsături generale',
 'Reținerea rangului 3 și a cotei 10–15% dintre cazurile de BAT, cu implicare simetrică.',
 ['Textul le plasează a treia, după diabet și hipertensiune, în Europa și SUA.','Cota citată este de aproximativ 10-15% din aceste cazuri.','Diabetul și hipertensiunea le precedă, nu invers.','Rinichii sunt implicați simetric.','Afectarea interstițială apare în mod obișnuit.']],
 8,'Cota 10–15% este ușor de mutat pe locul 1 etiologic; distractorii neagă simetria și interstițiul din același paragraf.',['10-15% din aceste cazuri','a treia cea mai frecventă']),

q(69,['Investigarea bolilor glomerulare (Cadranul 36.9) poate evidenția:',
 ['Cilindri eritrocitari la microscopia urinară','Titru antistreptolizină-O crescut în nefrita poststreptococică','ANCA pozitivi în unele vasculite și anti-MBG pozitivi în sindromul Goodpasture','Crioglobuline crescute în crioglobulinemie','Imagistică renală caracteristic „rinichi de stază”, patognomonică pentru NLM'],'ABCD',1353,'Glomerulul și afectarea glomerulară — Cadranul 36.9',
 'Recunoașterea panelului serologic și urinar din Cadranul 36.9, fără a inventa un semn imagistic pentru NLM.',
 ['Cadranul listează eritrocite și cilindri eritrocitari.','ASO crescut figurează la nefrita poststreptococică.','ANCA și anti-MBG sunt încadrate la vasculite, respectiv Goodpasture.','Crioglobulinele crescute sunt menționate.','Imagistica renală este de obicei normală, nu patognomonică pentru NLM.']],
 8,'Cadranul grupează markeri reali ușor de permutat; distractorul inventează un semn imagistic inexistent.',['Titru antistreptolizina-O','Anticorpi anti membrană bazală']),

q(70,['Identificați afirmația corectă referitoare la hipoalbuminemia din sindromul nefrotic:',
 ['Este explicată integral prin faptul că ficatul nu poate sintetiza albumină','Rezultă doar din scăderea PCSK9, fără catabolism tubular','O explicație parțială este creșterea catabolismului proteinelor reabsorbite, în mare parte albumină, în tubii proximali','Apare numai când proteinuria depășește 70 g/zi, egalând aportul dietetic britanic','HDL crește constant, raportul LDL:HDL scăzând'],'C',1353,'Glomerulul și afectarea glomerulară — Hipoalbuminemia: catabolism tubular',
 'Recunoașterea explicației parțiale prin catabolismul albuminei reabsorbite în tubul proximal.',
 ['Ficatul sănătos sintetizează 10-12 g albumină pe zi; nu este incapabil.','PCSK9 este invocată la hiperlipidemie (internalizarea receptorilor LDL), nu ca mecanism unic al hipoalbuminemiei.','Textul oferă exact această explicație parțială: catabolismul proteinelor reabsorbite în tubii proximali.','Pragul citat pentru sindrom este 3,5 g/zi, nu 70 g.','HDL este neschimbat sau scăzut, iar raportul LDL:HDL crește.']],
 8,'Capcana mută PCSK9 (lipidică) pe hipoalbuminemie și ignoră catabolismul tubular, detaliul nefolosit din același paragraf.',['tubii proximali','catabolismului proteinelor']),

q(71,['În tratamentul edemelor din sindromul nefrotic, dincolo de dozele de furosemid deja consacrate:',
 ['Edemul mucoasei intestinale poate îngreuna absorbția diureticelor, fiind necesară administrarea intravenoasă inițial','Poate fi acceptat un grad moderat de edeme pentru a evita hipotensiunea posturală','Hipercoagulabilitatea se datorează pierderii de antitrombină urinară și creșterii producției hepatice de fibrinogen','Restricția hidrică strictă și mobilizarea forțată înlocuiesc diureticul de ansă','Amiloridul este contraindicat din cauza hiperkaliemiei invariabile la toți nefroticii'],'ABC',1354,'Glomerulul și afectarea glomerulară — Edeme, absorbție și hipercoagulabilitate',
 'Corelarea edemului mucoasei (diuretic i.v.), a toleranței unui edem moderat și a axei antitrombină–fibrinogen.',
 ['Textul leagă edemul mucoasei intestinale de absorbția deficitară și de nevoia de cale i.v.','Un grad moderat de edeme este acceptat pentru a evita hipotensiunea posturală.','Pierderea de antitrombină și creșterea fibrinogenului explică starea de hipercoagulabilitate.','Diureticul de ansă rămâne baza; restricția hidrică forțată nu îl înlocuiește.','Amiloridul 5 mg/zi este adăugat la neresponsivi, cu monitorizarea potasiului, nu este interzis.']],
 8,'Detaliul mucoasei intestinale este ușor de ignorat în favoarea unei restricții hidrice „intuitive”.',['edemului mucoasei intestinale','antitrombină']),

q(72,['Patogeneza nefropatiei cu leziuni minime implică:',
 ['Celule stem CD34 imature diferențiate, mai degrabă decât limfocite T mature','IL-13, VEGF și expresia podocitară crescută a moleculei ANGPTL4','Medicamente precum AINS, litiu, cefalosporine, rifampicină, ampicilină, bisfosfonați și sulfasalazină','Depozite liniare de IgG anti-MBG, identice bolii Goodpasture','Infecții mai rare, precum VHC, HIV și tuberculoză'],'ABCE',1354,'Glomerulul și afectarea glomerulară — NLM: patogeneză și triggeri',
 'Reținerea axei CD34/IL-13/ANGPTL4 și a listei de medicamente, fără a atribui NLM un pattern anti-MBG.',
 ['Textul atribuie NLM celulelor stem CD34 imature, nu limfocitelor T mature.','IL-13, VEGF și ANGPTL4 sunt citate ca afectând funcția podocitelor.','Lista de medicamente este explicită.','Imunofluorescența în NLM nu evidențiază complexe imune sau anti-MBG.','VHC, HIV și tuberculoza sunt cauze mai rare.']],
 8,'Distractorul împrumută patternul liniar al bolii anti-MBG pe o glomerulopatie fără depozite imune.',['celulele stern CD34','ANGPTL4']),

q(73,['Sindromul nefrotic congenital de tip finlandez, dincolo de frecvența 1/8.200:',
 ['Este autozomal recesiv, prin mutații ale nefrinei, proteină transmembranară a fantei de filtrare','Poate fi diagnosticat intrauterin, α-fetoproteina crescută în lichidul amniotic fiind o caracteristică frecventă','Progresează persistent spre boala renală terminală','Răspunde prompt la prednisolonul pediatric standard, remisiunea fiind regula','Analiza mutațiilor în SNRS ar putea fi oferită persoanelor cu debut înainte de 25 de ani'],'ABCE',1355,'Glomerulul și afectarea glomerulară — Nefrotic congenital: AFP și genetica SNRS',
 'Completarea itemului de frecvență cu transmiterea AR, AFP amniotică, progresia spre ESRD și pragul de 25 de ani pentru analiza mutațiilor.',
 ['Transmiterea autozomal recesivă și nefrina ca proteină a fantei sunt explicite.','AFP crescută în lichidul amniotic permite diagnosticul intrauterine.','Progresia persistentă către BRT este caracteristică.','Formele genetice sunt considerate rezistente la corticosteroizi.','Textul propune analiza mutațiilor la SNRS cu debut înainte de 25 de ani.']],
 8,'Capcana clasică rămâne „răspunsul la steroizi”; se adaugă AFP amniotică și pragul de 25 de ani, nefolosite anterior.',['lichidul amniotic','înainte de vârsta de 25 de ani']),

q(74,['Variantele histologice ale GSFS includ:',
 ['Varianta cu leziunea vârfului glomerular („tip lesion”), cu scleroză la polul tubular și răspuns favorabil la corticosteroizi','Varianta colabantă, cu podocite tumefiate și vacuolate, frecventă în HIVAN','Varianta celulară, cu hipercelularitate segmentară care ocluzează lumenul capilar în cel puțin un glomerul','Glomerulii de la joncțiunea corticomedulară sunt primii afectați și pot fi ratați la biopsia transcutanată','Varianta „tip lesion” este patognomonică GSFS secundare prin obezitate, fără răspuns la steroizi'],'ABCD',1355,'Glomerulul și afectarea glomerulară — GSFS: variante histologice',
 'Diferențierea variantelor tip/colabantă/celulară și a riscului de diagnostic greșit de NLM prin ratarea glomerulilor corticomedulari.',
 ['Tip lesion are scleroză la polul tubular și evoluție mai benignă, cu răspuns favorabil la steroizi.','Varianta colabantă este descrisă în HIVAN.','Varianta celulară ocluzează lumenul prin hipercelularitate segmentară.','Glomerulii corticomedulari sunt primii afectați și pot lipsi din biopsie.','Tip lesion este a formei cu evoluție benignă, nu marca GSFS secundare.']],
 8,'Cele cinci variante sunt ușor de permutat; distractorul mută „tip lesion” pe forma secundară.',['tip lesion','joncţiunii corticomedulare']),

q(75,['Etiologia GSFS primare și opțiunile din recidiva post-transplant:',
 ['Un factor circulant de permeabilitate provoacă proteinuria; identitatea rămâne necunoscută, citokina 1 cardiotrophin-like fiind un candidat','suPAR este considerat puțin probabil factorul cauzal, pe baza dovezilor recente','Abataceptul (anti-CD80) a fost folosit cu un anumit succes la hiperexpresia podocitară a CD80','Gelul cu ACTH topic a fost utilizat cu succes în cazurile refractare post-transplant','suPAR rămâne factorul cauzal cert, plasmafereza fiind inutilă'],'ABCD',1356,'Glomerulul și afectarea glomerulară — GSFS primară: factorul de permeabilitate',
 'Disocierea candidatului cardiotrophin-like de suPAR și recunoașterea abataceptului/ACTH în recidiva de grefă.',
 ['Textul descrie factorul circulant și îl propune pe citokina 1 cardiotrophin-like.','Dovezile recente fac puțin probabil ca suPAR să fie cauzal.','Abataceptul este citat în hiperexpresia CD80.','Gelul ACTH topic figurează la cazurile refractare post-transplant.','suPAR este tocmai respins ca factor cauzal; plasmafereza are rezultate modeste, nu este declarată inutilă.']],
 8,'suPAR, o capcană „la modă”, este explicit respins în text; distractorul îl reinstaurează.',['cardiotrophin-like','Abatacept']),

q(76,['Un bărbat tânăr de culoare, HIV-pozitiv, prezintă proteinurie nefrotice și colaps glomerular la biopsie. Referitor la HIVAN sunt adevărate:',
 ['Infecția directă a podocitelor cu HIV-1 se asociază cu pierderea factorului tumoral Wilms și a sinaptopodinei','Terapia antiretrovirală poate determina reversibilitatea leziunilor dacă este inițiată precoce','Prezentarea asociază proteinurie nefrotice, edeme și BCR, care poate fi cu progresie rapidă','Leziunea este identică nefropatiei cu leziuni minime, fără colaps capilar','ARV este inutil după apariția proteinuriei, leziunea fiind ireversibilă din start'],'ABC',1356,'Glomerulul și afectarea glomerulară — HIVAN: reversibilitatea sub ARV',
 'Corelarea histologiei colabante cu reversibilitatea sub terapie antiretrovirală precoce.',
 ['Pierderea markerilor Wilms și sinaptopodină este explicită.','ARV poate determina reversibilitatea dacă este început precoce.','Tabloul nefrotic cu BCR rapid progresivă este descris.','HIVAN este varianta colabantă, nu NLM.','Textul leagă recuperarea de inițierea precoce a ARV, nu de ireversibilitate.']],
 8,'Vigneta cere legătura colaps–ARV; distractorii o confundă cu NLM sau neagă reversibilitatea.',['factorul tumoral Wilms','Terapia antiretrovirală']),

q(77,['Glomerulonefrita membranoasă secundară, fără anti-PLA2R/THSD7A, se asociază cu:',
 ['Medicamente precum penicilamină, aur, AINS, probenecid, mercur și captopril','Boli autoimune (LES, tiroidită) și infecții (VHB, VHC, schistosomiază, Plasmodium malariae)','Cancere (plămân, colon, stomac, sân, limfom)','Sarcoidoză și siclemie','Prezența constantă a anti-PLA2R, care definește forma secundară'],'ABCD',1357,'Glomerulul și afectarea glomerulară — GN membranoasă secundară: cauze',
 'Recunoașterea spectrului medicamentos, infecțios, neoplastic și de sistem, cu absența anti-PLA2R.',
 ['Lista de medicamente este din text.','LES, tiroidită, VHB/C, schistosomiază și malariae figurează.','Cancerele enumerate sunt explicite.','Sarcoidoza și siclemia sunt la „alte cauze”.','Forma secundară este definită tocmai prin absența anti-PLA2R/THSD7A.']],
 8,'Distractorul inversează markerul serologic care deosebește forma autoimună de cea secundară.',['penicilamină','THSD7A']),

q(78,['Anticorpii anti-THSD7A în glomerulopatia membranoasă sunt identificați la:',
 ['Aproximativ 75% dintre pacienții PLA2R-pozitivi, ca antigen major','Aproximativ 3% din cazurile PLA2R-pozitive și 10% dintre pacienții PLA2R-negativi, inclusiv în asociere cu o neoplazie','Peste 90% dintre formele secundare medicamentoase','Numai copiii cu sindrom nefrotic congenital finlandez','Toți pacienții cu anti-MBG, definind suprapunerea Goodpasture'],'B',1357,'Glomerulul și afectarea glomerulară — THSD7A versus PLA2R',
 'Reținerea cotelor 3% (PLA2R-pozitivi) și 10% (PLA2R-negativi) și a asocierii cu neoplazie.',
 ['75% este cota anti-PLA2R IgG4, nu a THSD7A.','Textul dă 3% în cazurile PLA2R-pozitive și 10% la PLA2R-negativi, cu asociere neoplazică.','Forma secundară este seronegativă pentru acești anticorpi.','Nefrina, nu THSD7A, definește forma finlandeză.','Anti-MBG aparține altei boli.']],
 8,'Permutează 75%, 3% și 10% între PLA2R și THSD7A, capcana numerică a aceluiași paragraf.',['3% din cazurile PLA2R-pozitive','10% dintre pacienţii PLA2R-negativi']),

q(79,['Amiloidoza AL, dincolo de proteina Bence Jones și Roșu Congo:',
 ['Rareori apare înainte de vârsta de 40 de ani','Macroglosia apare în aproximativ 10% din cazuri, iar purpura periorbitală în 15%','Sindromul de tunel carpian poate fi o manifestare precoce','Se asociază cu mielom, macroglobulinemie Waldenström sau limfom non-Hodgkin','Macroglosia este prezentă în peste 80% din amiloidoza AA, nu în AL'],'ABCD',1358,'Glomerulul și afectarea glomerulară — Amiloidoza AL: clinic',
 'Fixarea vârstei (>40 de ani), a cotelor 10%/15% (macroglosie/purpură) și a asocierilor limfoproliferative.',
 ['Textul notează raritatea sub 40 de ani.','Macroglosia ~10% și purpura periorbitală 15% sunt explicite.','Tunelul carpian este citat ca manifestare precoce.','Mielomul, Waldenström și LNH sunt asocierile.','Macroglosia nu este o caracteristică a AA; cotele 10%/15% aparțin AL.']],
 8,'Cotele 10% și 15% sunt ușor de mutat pe forma AA, care tocmai nu are macroglosie.',['aproximativ 10% din cazuri','purpura periorbitală în 15%']),

q(80,['Diagnosticul amiloidozei cu afectare renală se sprijină pe:',
 ['Rinichi adesea măriți imagistic','Scintigrafia cu amiloid seric P (SAP) radiomarcat pentru cuantificarea depozitelor in vivo','Biopsie din rect, gingii, grăsime abdominală sau miocard, dacă histologia renală nu poate fi obținută','Identificarea imunohistochimică a AL în doar ~40% din cazuri, față de aproape 100% în AA','Scintigrafia MAG3, care înlocuiește biopsia în toate formele de amiloidoză'],'ABCD',1358,'Glomerulul și afectarea glomerulară — Amiloidoza: SAP și biopsii extra-renale',
 'Completarea diagnosticului cu SAP, rinichi mari și siturile extra-renale, păstrând cota 40% versus 100%.',
 ['Rinichii sunt adesea crescuți în dimensiune.','SAP radiomarcat cuantifică depozitele in vivo.','Rect, gingii, grăsime abdominală și miocard sunt siturile alternative.','Cotele 40% versus aproape 100% sunt din text.','MAG3 evaluează obstrucția/perfuzia, nu amiloidul.']],
 8,'SAP este o tehnică puțin uzuală, ușor de confudat cu MAG3 din investigațiile de la începutul capitolului.',['amiloid seric P','grăsime abdominală']),

q(81,['Clasificarea Societății de Patologie Renală a nefropatiei diabetice (Cadranul 36.11):',
 ['Clasa I: îngroșare izolată a MBG (>395 nm la femei, >430 nm la bărbați), fără expansiune mezangială','Clasa IIb: expansiune mezangială severă, cu >25% din mezangiu mai mare decât aria medie a lumenului capilar','Clasa IV: glomeruloscleroză diabetică avansată și >50% glomeruloscleroză globală','Clasa I se definește prin noduli Kimmelstiel-Wilson în peste 50% din glomeruli','Podocituria precoce rezultă din epuizarea podocitelor prin apoptoză sau detașare'],'ABCE',1359,'Glomerulul și afectarea glomerulară — Nefropatia diabetică: praguri de clasă',
 'Aplicarea pragurilor în nanometri (clasa I) și a definiției IIb/IV, plus podocituria precoce.',
 ['Cadranul dă pragurile 395/430 nm pentru clasa I.','IIb cere >25% din mezangiu cu arii mai mari decât lumenul mediu.','Clasa IV combină scleroza avansată cu >50% glomeruloscleroză globală.','Nodulii Kimmelstiel-Wilson definesc clasa III, nu I.','Epuizarea podocitelor (apoptoză/detașare) duce la podociturie la începutul bolii.']],
 8,'Pragurile 395/430 nm și mutarea nodulilor KW pe clasa I sunt capcane de cadran.',['>395 nm la femei','Podociturie']),

q(82,['Intervenții adjuvante și factori de progresie în nefropatia diabetică:',
 ['Fumatul se asociază cu o rată de trei ori mai mare de progresie a bolii cronice de rinichi','Pentoxifilina încetinește scăderea RFG și proteinuria prin reducerea TNF-α, observație care necesită validare','Atrasentan (antagonist selectiv ETAR) combinat cu blocada SRA reduce albuminuria reziduală, cu nevoie de confirmare pe termen lung','Dulaglutida figurează, alături de liraglutidă și semaglutidă, printre agoniștii GLP-1 menționați','Fumatul este protector, rata de progresie scăzând de trei ori la fumători'],'ABCD',1359,'Glomerulul și afectarea glomerulară — Renoprotecție: fumat, pentoxifilină, ETAR',
 'Reținerea factorului ×3 al fumatului și a statutului încă nevalidat al pentoxifilinei și atrasentanului.',
 ['Cadranul 36.12 citează rata de trei ori mai mare de progresie la fumători.','Mecanismul TNF-α și nevoia de validare sunt explicite.','Atrasentanul este descris ca reducer al albuminuriei reziduale, cu confirmare ulterioară.','Dulaglutida este în lista de agoniști GLP-1.','Relația cu fumatul este inversă față de distractor.']],
 8,'Inversează direcția fumatului (×3 progresie) și tratează două observații preliminare ca și cum ar fi infirmate.',['trei ori mai mare','Atrasentan']),

q(83,['Proteinuria izolată fără hematurie, la un pacient asimptomatic:',
 ['Măsoară de obicei sub 1 g/zi, cu funcție renală normală','Peste 50% dintre acești pacienți au proteinurie posturală (benignă)','Este patognomonică pentru amiloidoză și impune biopsie imediată la toți','Exclude o glomerulopatie gravă, fiind invariabil tranzitorie febrilă','Pragul de 3,5 g/zi o încadrează automat ca sindrom nefritic'],'AB',1360,'Glomerulul și afectarea glomerulară — Proteinurie izolată posturală',
 'Recunoașterea cotei >50% de proteinurie posturală benignă la proteinuria sub 1 g/zi.',
 ['Textul dă sub 1 g/zi cu funcție normală.','Peste 50% au proteinurie posturală benignă.','Poate fi totuși semnul precoce al unei leziuni grave (membranoasă, IgA, GSFS, diabetică, amiloid).','Formele febrile/ICC sunt ușoare sau tranzitorii, dar nu epuizează diagnosticul.','3,5 g/zi definește sindromul nefrotic, nu nefritic.']],
 8,'Cota 50% posturală este ușor de transformat într-o „patognomonie” de amiloid sau într-un sindrom nefritic.',['Peste 50%','proteinurie post�rală']),

q(84,['„Semiluna” din GNRP și spectrul clinic al glomerulonefritei:',
 ['Semiluna este un agregat de macrofage și celule epiteliale în spațiul lui Bowman','GNRP evoluează cu insuficiență renală acută în săptămâni până la luni, cu necroză glomerulară focală ± semilune','Nefrita acută se diferențiază de GNRP prin lipsa necrozei celulare și a semilunelor, pe un continuum','Cadranul 36.13 distinge pattern liniar, granular și pauci-imun','Toate GNRP sunt pauci-imune, semiluna fiind un depozit liniar de IgG'],'ABCD',1360,'Glomerulul și afectarea glomerulară — GNRP: semiluna și continuumul',
 'Definirea histologică a semilunei și plasarea nefritei acute versus GNRP pe același spectru, după Cadranul 36.13.',
 ['Definiția cu macrofage și celule epiteliale este din text.','Fereastra săptămâni-luni și necroza focală sunt explicite.','Lipsa necrozei/semilunelor deosebește nefrita acută, pe un continuum.','Cele trei patternuri de imunofluorescență sunt în cadran.','GNRP poate fi liniară, granulară sau pauci-imună; semiluna nu este un depozit de IgG.']],
 8,'Confuzia semilună = depozit liniar IgG este capcana clasică; textul o definește celular.',['spaţiul lui Bowman','Cadranul 36,13']),

q(85,['Precizați enunțul corect privind tratamentul glomerulonefritei poststreptococice:',
 ['Profilaxia cu penicilină pe termen lung după dezvoltarea GN este susținută de dovezi solide','La adult nu este necesară nicio urmărire, prognosticul fiind identic copilului','Corticosteroizii sunt linia întâi la toți copiii, înaintea controlului tensional','Lipsesc dovezi în sprijinul profilaxiei cu penicilină pe termen lung după dezvoltarea GN; la adult se recomandă monitorizare anuală a TA și a creatininei','Abcesul visceral cu complement normal se tratează doar cu plasmafereză, fără drenaj'],'D',1361,'Glomerulul și afectarea glomerulară — GNPS: tratament și urmărire',
 'Recunoașterea absenței profilaxiei cu penicilină și a urmăririi anuale la adult.',
 ['Textul afirmă că lipsesc dovezi pentru profilaxia cu penicilină.','Un număr mic de adulți dezvoltă HTA/BCR ulterior, deci urmărirea anuală este cerută.','Tratamentul vizează TA, diuretice și dializă; steroizii doar dacă recuperarea este lentă.','Aceasta este afirmația din text.','Abcesul visceral se tratează cu antibiotice și drenaj, cu recuperare în ~50%.']],
 8,'Intuiția „penicilină de durată după streptococ” este tocmai infirmată de text.',['profilaxiei cu penicilină','monitorizarea anuală']),

q(86,['Glomerulonefrita din endocardită, șunt infectat sau abces visceral:',
 ['Leziunile din endocardită/șunt sunt de obicei focale și segmentare, putând exista GN cu semilune mai ales cu Staphylococcus aureus','Antibioticele sau eradicarea chirurgicală a infecției fulminante duc de obicei la recuperarea funcției','În abcesul visceral (în principal pulmonar) complementul este normal, iar depozitele imune lipsesc la biopsie','Recuperarea completă după antibiotice și drenaj survine în aproximativ 50% din abcese','Complementul este profund scăzut, iar plasmafereza înlocuiește drenajul chirurgical'],'ABCD',1361,'Glomerulul și afectarea glomerulară — GN infecțioasă non-streptococică',
 'Contrastul endocardită/șunt (focal-segmentar, S. aureus) versus abces visceral (C normal, fără depozite, recuperare ~50%).',
 ['Histologia focal-segmentară și semilunele cu S. aureus sunt din text.','Eradicarea infecției duce de obicei la recuperare.','Complement normal și absența depozitelor deosebesc abcesul visceral.','Cota de ~50% este explicită.','În abces complementul este normal; drenajul rămâne esențial.']],
 8,'Capcana este aplicarea hipocomplementemiei poststreptococice pe abcesul visceral, unde C este normal.',['Staphylococcus aureus','aproximativ 50% din cazuri']),

q(87,['Patogeneza nefropatiei cu IgA, dincolo de clasificarea Oxford:',
 ['Un studiu genomic european a arătat o asociere puternică pe cromozomul 6p, în regiunea CMH/DQ și HLA-B','Există o anomalie de galactozilare O-linkată în regiunea balama a IgA1','Receptorii CD89 (celule mieloide) și CD71 (mezangiale) sunt implicați','Asocieri includ boli hepatice cronice, carcinoame bronșice, spondiloartrită, boală celiacă, mycosis fungoides și psoriazis','Antigenul țintă este PLA2R, identic glomerulopatiei membranoase autoimune'],'ABCD',1362,'Glomerulul și afectarea glomerulară — Nefropatia IgA: patogeneză și asocieri',
 'Reținerea locusului 6p, a defectului de galactozilare și a asocierilor extra-renale, distincte de PLA2R.',
 ['Asocierea 6p CMH/DQ și HLA-B este din text.','Anomalia de galactozilare O-linkată este citată.','CD89 și CD71 figurează ca receptori IgA.','Lista de boli asociate este explicită.','PLA2R aparține membranoasei, nu nefropatiei IgA.']],
 8,'Distractorul mută autoantigenul membranoasei (PLA2R) pe cea mai frecventă GN mondială.',['cromozomul 6p','galactozilarea']),

q(88,['Boala membranei bazale glomerulare subțiri și granița cu Alport:',
 ['Se transmite autozomal dominant și se prezintă cu hematurie glomerulară microscopică persistentă','Diagnosticul se face prin biopsie, cu subțierea MBG capilare la microscopia electronică','Prognosticul funcției renale este de obicei foarte bun, deși unii dezvoltă insuficiență de-a lungul deceniilor','Niciun tratament nu are un beneficiu cunoscut','Transmiterea este legată de X prin COL4A5, cu surditate prezentă la toți heterozigoții'],'ABCD',1362,'Glomerulul și afectarea glomerulară — MBG subțire versus Alport',
 'Separarea hematuriei familiale benigne (AD, ME, prognostic bun) de Alport legat de X.',
 ['Transmiterea AD și hematuria persistentă sunt din text.','Subțierea la ME stabilește diagnosticul.','Prognosticul este de obicei foarte bun.','Niciun tratament nu are beneficiu cunoscut.','COL4A5 legat de X definește Alport, nu MBG subțire; proteinuria în Alport este ușoară, nu „surditate la toți heterozigoții”.']],
 8,'Granița vagă Alport–MBG subțire este exploatată prin mutarea geneticii COL4A5 pe forma AD benignă.',['autosomal dominant','microscopie electronică']),

q(89,['Boala anti-MBG, dincolo de epidemiologie și de pragul creatininei:',
 ['Anticorpii vizează epitopul α3(IV) NC1; anticorpii împotriva α1, α2 și α3 și domeniile NC1 nu determină GNRP în formularea textului despre specificitate','Expunerea la hidrocarburi sau fum de țigară este invocată pentru a descoperi epitopii criptici','Formarea semilunelor este facilitată de IL-12 și interferon-gamma','Netratată, autoanticorpii dispar spontan în decurs de 3 ani; afecțiunea este de tip „single hit”','Boala urmează cicluri remisie–reactivare ca LES, autoanticorpii persistând tot restul vieții'],'ABCD',1363,'Glomerulul și afectarea glomerulară — Anti-MBG: epitop, mediu și single hit',
 'Reținerea epitopului criptici (hidrocarburi/fum), a IL-12/IFN-γ și a dispariției spontane a anticorpilor în 3 ani.',
 ['Specificitatea pentru α3(IV) NC1 este subliniată.','Hidrocarburile și fumul de țigară sunt factorii de mediu citați.','IL-12 și IFN-γ facilitează semilunele.','Dispariția în 3 ani și caracterul single hit, cu reaparitia CD25+, sunt explicite.','Textul o deosebește tocmai de bolile cu remisie/reactivare.']],
 8,'Capcana „ca LES” este infirmată de dispariția anticorpilor în 3 ani și de formula single hit.',['fum de ţigară','single hit']),

q(90,['În vasculitele ANCA-asociate, dincolo de schema clasică de inducție:',
 ['Rituximabul este la fel de eficient în inducție pe termen scurt (6–12 luni), cu rate similare de evenimente adverse','Studiul PEXIVAS (peste 700 de pacienți) nu a arătat că plasmafereza influențează mortalitatea sau evoluția către BRT','Glucocorticoizii orali în doze mai mici au redus infecțiile grave, fără control mai puțin eficient al bolii','Colonizarea căilor aeriene superioare cu Staph. aureus crește riscul de recidivă; sulfametoxazol/trimetoprim reduce rata recidivelor','PEXIVAS a impus plasmafereza la toți pacienții cu GNRP ANCA, steroizii în doze mici fiind inutili'],'ABCD',1364,'Glomerulul și afectarea glomerulară — ANCA: PEXIVAS, rituximab de inducție, S. aureus',
 'Integrarea PEXIVAS (fără beneficiu al plasmaferezei; steroizi mai mici) cu rituximabul de inducție și cu rolul S. aureus.',
 ['Rituximabul de inducție 6-12 luni este echivalent.','PEXIVAS nu a influențat mortalitatea/BRT prin plasmafereză.','Steroizii în doze mai mici au redus infecțiile grave.','S. aureus și co-trimoxazolul sunt legate de recidivă.','Concluzia PEXIVAS este inversă față de distractor.']],
 8,'PEXIVAS răstoarnă intuiția „plasmafereză la GNRP severă”; distractorul reinstaurează dogma pre-studiu.',['PEXIVAS','Staph. aureus']),

q(91,['Nefropatia cu IgM se caracterizează prin:',
 ['Creșterea celularității mezangiale cu depozite granulare de IgM și complement','Răspuns la steroizi de doar 50%, iar 10–30% dezvoltă BCR progresivă și GSFS secundară','Prognostic identic NLM, cu remisiune la peste 95% după o cură scurtă de prednison','Depozite liniare de IgG anti-MBG, fără proliferare mezangială','Absența completă a hematuriei, prezentarea fiind doar sindrom nefritic pur'],'AB',1365,'Glomerulul și afectarea glomerulară — Nefropatia IgM',
 'Deosebirea de NLM prin răspunsul de 50% la steroizi și riscul 10–30% de BCR/GSFS.',
 ['Histologia mezangială cu IgM și complement este din text.','Răspunsul 50% și cota 10-30% sunt explicite.','Prognosticul nu este tot timpul bun, spre deosebire de NLM.','Patternul liniar aparține bolii anti-MBG.','Pacienții au hematurie și sindrom nefrotic.']],
 8,'Permutează rata de răspuns a NLM (>95%) pe nefropatia IgM, unde steroizii reușesc doar pe jumătate.',['răspunsul la steroizi este de doar 50%','10% şi 30%']),

q(92,['Identificați afirmația corectă referitoare la nefropatia C1q:',
 ['Se deosebește de nefropatia IgM prin depozite mezangiale de C1q, colorare intensă la imunofluorescență și absența incluziunilor tubuloreticulare la ME','Este identică nefritei lupice de clasă IV, incluziunile tubuloreticulare fiind constant prezente','Se colorează DNAJB9, fibrilele având 20–30 nm','Antigenul este PLA2R, ca în membranoasa autoimună','Complementul C1q lipsește, diagnosticul bazându-se pe ANCA'],'A',1365,'Glomerulul și afectarea glomerulară — Nefropatia C1q versus „lupus seronegativ”',
 'Recunoașterea capcanei de lupus seronegativ: C1q intens la IF, fără incluziuni tubuloreticulare.',
 ['Textul distinge C1q de IgM tocmai prin colorarea C1q și absența incluziunilor tubuloreticulare.','Incluziunile tubuloreticulare (interferon-α) lipsesc, spre deosebire de lupus.','DNAJB9 aparține glomerulopatiei fibrilare.','PLA2R aparține membranoasei.','Diagnosticul este histologic/IF, nu ANCA.']],
 8,'Capcana „lupus seronegativ” este numită în text; distractorii mută markeri din boli învecinate (DNAJB9, PLA2R, ANCA).',['depunerilor de Clq','incluziunilor tubuloreticulare']),

q(93,['Gammopatia monoclonală cu semnificație renală (MGRS) include:',
 ['Boli de depozit: AL, GN fibrilară/imunotactoidă, MIDD, GN proliferativă cu Ig monoclonale și tubulopatia cu lanțuri ușoare','Boli de precipitare: GN crioglobulinemică','Boli cu activarea complementului: nefropatia C3 cu paraproteinemie și SHU atipic','Bortezomib, rituximab și posibil daratumumab au rezultate mai bune decât imunosupresia convențională','Imunosupresia convențională este superioară bortezomibului, paraproteina neavând rol renal'],'ABCD',1366,'Glomerulul și afectarea glomerulară — Spectrul MGRS și terapia țintită',
 'Maparea celor trei categorii MGRS și a superiorității bortezomib/rituximab/daratumumab față de imunosupresia clasică.',
 ['Lista bolilor de depozit este din text.','Crioglobulinemica figurează la precipitare.','C3 cu paraproteină și SHU atipic sunt la activarea complementului.','Cele trei agenți sunt citați cu rezultate mai bune.','Convenționala nu a demonstrat beneficii semnificative.']],
 8,'Trei categorii (depozit/precipitare/complement) sunt ușor de amestecat; distractorul inversează ierarhia terapeutică.',['daratumumab','MGRS']),

q(94,['Glomerulopatia cu fibronectină:',
 ['Este autozomal dominantă, etiologia sugerată fiind mutația uteroglobinei cu pierderea funcției','Depunerile fibrilare sunt negative Roșu Congo, similar formelor fibrilară și imunotactoidă','Se prezintă cu proteinurie între 20 și 40 de ani, apoi HTA, hematurie microscopică și progresie lentă spre BRT','Fibronectina este o glicoproteină dimerică (~250 kDa pe subunitate)','Se colorează intens Roșu Congo, fiind o variantă de amiloidoză AL pediatrică'],'ABCD',1366,'Glomerulul și afectarea glomerulară — Glomerulopatia cu fibronectină',
 'Deosebirea de amiloid prin negativitatea Roșu Congo, genetica AD/uteroglobină și vârsta 20–40 de ani.',
 ['Transmiterea AD și uteroglobina sunt din text.','Negativitatea Roșu Congo este comună celor trei glomerulopatii fibrilare non-amiloid.','Fereastra 20-40 de ani și progresia lentă sunt explicite.','Masa ~250 kDa pe subunitate este citată.','Roșu Congo negativ o deosebește de amiloid.']],
 8,'Calibrul și colorația sunt permutabile cu amiloidul; uteroglobina este detaliul genetic nefolosit.',['uteroglobinei','20 şi 40 de ani']),

q(95,['Clasele I și II ale nefritei lupice (Cadranul 36.16), mai puțin abordate:',
 ['Clasa I este mezangială minimă, cu depozite imune dar glomeruli normali la microscopia optică, asimptomatică','Clasa II este proliferativ mezangială, cu boală renală ușoară clinic','Nefrita lupică de tip I nu necesită tratament specific','Tipul II are de obicei un curs benign; o parte dintre pacienți primesc hidroxiclorochină și/sau steroizi','Clasa I se tratează ca GNRP, cu plasmafereză și ciclofosfamidă i.v. de la diagnostic'],'ABCD',1366,'Glomerulul și afectarea glomerulară — Nefrita lupică: clasele I–II',
 'Aplicarea definițiilor ISN/RPS pentru clasele ușoare și a abținerii terapeutice la clasa I.',
 ['Cadranul descrie clasa I ca mezangială minimă, asimptomatică.','Clasa II are hipercelularitate mezangială și boală ușoară.','Tipul I nu necesită tratament specific.','Hidroxiclorochina și/sau steroizii sunt opțiuni la o parte din clasa II.','Plasmafereza/ciclofosfamida aparțin formelor proliferative severe, nu clasei I.']],
 8,'Capcana este „overtreatment” al clasei I, tratată ca GNRP, deși cadranul o descrie asimptomatică.',['Clasa I','hidroxiclorochină'],[1367]),

q(96,['Poliarterita nodoasă cu afectare renală:',
 ['Dilatarea anevrismală a arterelor medii se manifestă prin hipertensiune, polineuropatie și infarcte ischemice viscerale','Anevrismele pot fi evidențiate prin arteriografie renală; pacienții sunt tipic ANCA-negativi','Predomină la bărbați și vârstnici și se poate asocia cu droguri și hepatita B','Evoluția este de obicei GNRP fulminantă ANCA-pozitivă, identică MPA','Imunosupresia este mai eficientă decât în poliangeita microscopică'],'ABC',1368,'Implicarea rinichiului în alte afecțiuni — Poliarterita nodoasă',
 'Deosebirea PAN (artere medii, ANCA-negativ, HTA severă lent progresivă) de MPA pauci-imună.',
 ['Anevrismele arterelor medii și tabloul ischemic sunt din text.','Arteriografia și ANCA-negativitatea sunt explicite.','Sexul masculin, vârsta și VHB/drogurile sunt citate.','Evoluția rapid progresivă este de obicei rară; nu este o vasculită ANCA.','Imunosupresia este mai puțin eficientă decât în MPA.']],
 8,'Confuzia PAN–MPA (ANCA, semilune) este firul roșu; textul le desparte prin calibrul arterial și serologie.',['ANCA negativi','hepatita B']),

q(97,['O gravidă dezvoltă hipertensiune și proteinurie cu debut rapid. Următoarele afirmații despre glomerulopatia din preeclampsie sunt adevărate:',
 ['Leziunea asociază inflamație endotelială marcată și obliterarea lumenului capilar; la 30% modificările persistă ≥6 luni după naștere','sFlt1 supraexprimat antagonizează VEGF și factorii de creștere placentari, provocând disfuncție endotelială','Anticorpii anti-agoniști ai receptorilor angiotensinei II cresc NADPH-oxidaza placentară','Proteinuria dispare invariabil în 48 de ore, fără leziune histologică','Cauza este o vasculită ANCA-PR3 a arteriolelor glomerulare'],'ABC',1368,'Implicarea rinichiului în alte afecțiuni — Preeclampsia: sFlt1 și VEGF',
 'Corelarea endoteliozei, a persistenței la 30%/6 luni și a axei sFlt1–VEGF.',
 ['Endotelioza și cota de 30% la 6 luni sunt din text.','sFlt1 antagonizează VEGF/PlGF.','Anticorpii anti-AT1 cresc NADPH-oxidaza.','Leziunile pot fi ireversibile; nu dispar în 48 de ore la toate.','Nu este o vasculită ANCA.']],
 8,'Vigneta obstetrică împinge spre „totul trece după naștere”; textul citează persistență la 30% și axa sFlt1.',['sFlt1','30% dintre pacienţi']),

q(98,['Glomerulonefrita paraneoplazică se asociază, după tipul tumorii, cu:',
 ['Timom sau Hodgkin: polarizare Th2 și IL-13, cu NLM, GNMC sau membranoasă','Limfom B și leucemie: Ig monoclonală, crioglobulină, eventual VHC','Policitemie vera, trombocitemie esențială sau mielofibroză: GSFS legată de PDGF din trombocite','Carcinom epitelial: complexe subepiteliale IgG1 și IgG2, utile pentru a recunoaște membranoasa paraneoplazică','Toate tumorile solide produc identic boală anti-MBG, fără legătură cu linia celulară'],'ABCD',1368,'Implicarea rinichiului în alte afecțiuni — GN paraneoplazică',
 'Maparea perechilor tumoră–leziune (Th2/IL-13, crioglobulină, PDGF, IgG1/IgG2).',
 ['Timomul/Hodgkin și axa Th2/IL-13 sunt din text.','Limfomul B/leucemia sunt legate de Ig monoclonală.','Trombocitoza severă poate induce GSFS prin PDGF.','IgG1/IgG2 subepiteliale ajută diagnosticul membranoasei paraneoplazice.','Leziunea depinde de tipul tumorii, nu este anti-MBG universal.']],
 8,'Patru perechi tumoră–histologie sunt concepute să fie permutabile; distractorul le reduce la Goodpasture.',['IL-13','lgG1 şi lgG2']),

q(99,['Precizați enunțul corect privind pielonefrita xantogranulomatoasă:',
 ['Este o infecție cronică interstițială, cel mai adesea cu E. coli, tratată doar oral 3 zile','Este bilaterală în toate cazurile și se vindecă prin hidratare','Este o infecție cronică interstițială rară, cel mai adesea cu Proteus, de obicei unilaterală, asociată cu calcul coraliform; tratamentul de elecție este nefrectomia','Se identifică prin MAG3, nefrectomia fiind contraindicată','Este identică NTIU, cu uveită și anti-PCR'],'C',1385,'Nefritele tubulointerstițiale — Pielonefrita xantogranulomatoasă',
 'Recunoașterea triadei Proteus–calcul coraliform–nefrectomie, distinctă de NTI medicamentoasă.',
 ['E. coli și cura scurtă orală nu corespund descrierii.','Este de obicei unilaterală.','Textul o leagă de Proteus, calcul coraliform, CT cu arii transparente și nefrectomie.','Diagnosticul este CT; antibioticele rareori eradică infecția.','NTIU este o altă entitate (uveită, steroizi).']],
 8,'Nefrectomia ca elecție este contraintuitivă față de o „pielonefrită” obișnuită.',['Proteus-ului','calcul coraliform']),

q(100,['Sindromul nefritei tubulointerstițiale cu uveită (NTIU):',
 ['Asociază uveită, NTI acută, pierdere ponderală, anemie și VSH crescut de cauză necunoscută','Apare frecvent în copilărie, dar și la adulți, mai frecvent la femei','Se poate asocia cu autoanticorpi anti-PCR modificată','Tratamentul este o cură prelungită de corticosteroizi, care ameliorează funcția renală și uveita','Este o infecție cu Proteus care impune nefrectomie, uveita fiind o coincidență'],'ABCD',1386,'Nefritele tubulointerstițiale — Sindromul NTIU',
 'Recunoașterea tabloului uveită–NTI–VSH, a predilecției de sex și a răspunsului la steroizi prelungiți.',
 ['Cele cinci elemente de prezentare sunt din text.','Copilăria și predominanța feminină la adult sunt citate.','Anti-PCR modificată este menționată.','Cura prelungită de steroizi ameliorează ambele ținte.','Nefrectomia aparține xantogranulomatoasei, nu NTIU.']],
 8,'Distractorul mută nefrectomia din xantogranulomatoasă pe un sindrom steroid-responsiv cu uveită.',['uveită','anti￾proteina C reactivă']),

q(101,['Nefropatia analgetică:',
 ['Urmează consumului cronic de analgezice în doze mari (clasic fenacetină, mai recent AINS)','Apare mai frecvent la femeile de vârstă medie','Tabloul include anemie, BCR, ITU, hematurie sau obstrucție prin papilă necrozată migrată','Poate asocia pierdere de lichide și de sare','Este o glomerulopatie cu semilune ANCA-pozitivă, fără necroză papilară'],'ABCD',1386,'Nefritele tubulointerstițiale — Nefropatia analgetică',
 'Corelarea fenacetinei/AINS cu necroza papilară, predilecția feminină și pierderea de sare.',
 ['Fenacetina și AINS sunt agenții citați.','Femeile de vârstă medie predomină.','Anemia, BCR, ITU, hematuria și obstrucția prin papilă sunt listate.','Pierderea de lichide și sare este menționată.','Este o NTI cronică cu necroză papilară, nu o vasculită ANCA.']],
 8,'Necroza papilară și pierderea de sare sunt ușor de înlocuit cu un pattern glomerular ANCA.',['fenacetină','vârstă medie']),

q(102,['NTI acută produsă de infecții, dincolo de medicamentele din Cadranul 36.27:',
 ['Poate complica infecții cu Hantavirus, EBV, HIV, rujeolă, adenovirus, Legionella, Leptospira, Mycoplasma, Brucella sau Toxoplasma','Hantavirusul produce febră hemoragică cu NTI și poate fi fatal','La transplantați, CMV, polyoma (BK) și herpes sunt implicați','Medicamentele rămân cauza a ~70% din NTI acută, infecțiile ~15%, idiopaticul ~8%, NTIU ~5%','Hantavirusul este inofensiv, NTI infecțioasă fiind produsă doar de streptococ'],'ABCD',1385,'Nefritele tubulointerstițiale — NTI infecțioasă și Hantavirus',
 'Reținerea spectrului viral/bacterian și a cotelor din Cadranul 36.27 (70/15/8/5%).',
 ['Lista de agenți este din text.','Hantavirusul poate fi fatal.','CMV, BK și herpes figurează la transplantați.','Cotele cadranului sunt 70%, 15%, 8% și 5%.','Hantavirusul este citat ca potențial fatal, nu inofensiv.']],
 8,'Cotele 70/15/8/5% sunt permutabile; distractorul banalizează Hantavirusul.',['Hantavirus','70%}']),

q(103,['Prevenția nefropatiei de contrast, dincolo de oprirea metforminei:',
 ['Se minimizează doza și se folosesc substanțe izo-osmolare sau hipo-osmolare','Hidratarea cu 1 L ser fiziologic 0,9% sau 1 L bicarbonat 1,4% peri-procedural și 8–12 ore post-procedural','N-acetilcisteina 48 de ore înainte oferă cel mult un beneficiu marginal','Dopamina, teofilina și dializa profilactică nu sunt benefice','N-acetilcisteina înlocuiește hidratarea, iar dializa profilactică este standardul'],'ABCD',1392,'Boala cronică de rinichi — Contrast: hidratare, osmolalitate, NAC',
 'Ierarhizarea măsurilor (doză, osmolalitate, 1 L NaCl/bicarbonat) față de NAC marginal și de dopamină/dializă ineficiente.',
 ['Minimizarea dozei și contrastul izo/hipo-osmolar sunt din text.','Schema 1 L + 8-12 ore este explicită.','NAC are cel mult beneficiu marginal.','Dopamina, teofilina și dializa profilactică nu sunt benefice.','Hidratarea rămâne esențială; NAC nu o înlocuiește.']],
 8,'NAC „de protocoale vechi” este coborâtă la beneficiu marginal; distractorul o urcă peste hidratare.',['1 L ser fiziologic 0,9%','beneficiu mar￾ginal']),

q(104,['Nefropatia acută prin precipitare de fosfat:',
 ['Poate urma fosfatului de sodiu oral folosit la pregătirea investigațiilor gastrointestinale','Administrarea orală de fosfat este contraindicată în BCR, ICC, obstrucții digestive și hipercalcemie preexistentă','Biopsiile arată depuneri masive de fosfați; tratamentul este suportiv, cu dializă după necesități','Recuperarea renală este în general bună','Fosfatul oral protejează de nefropatia de contrast și este recomandat înaintea CT-ului cu iod'],'ABCD',1392,'Boala cronică de rinichi — Precipitarea de fosfat post-pregătire digestivă',
 'Recunoașterea fosfatului oral de pregătire ca nefrotoxină, a contraindicațiilor și a caracterului suportiv al tratamentului.',
 ['Pregătirea GI cu fosfat de sodiu oral este triggerul.','Lista de contraindicații este explicită.','Depunerile masive de fosfați și dializa după necesități sunt din text.','Recuperarea este în general bună.','Fosfatul oral precipită IRA, nu previne nefropatia de contrast.']],
 8,'Capcana este transformarea unei cauze de IRA (fosfat oral) într-o măsură „protectoare” peri-contrast.',['fosfatului de sodiu oral','depuneri masive de fosfaţi']),

q(105,['BCR, ca termen descriptiv, și situațiile cu reversibilitate probabilă:',
 ['Implică alterare de lungă durată (>3 luni), cu potențial progresiv','În majoritatea stadiilor 1–3 funcția nu continuă să se deterioreze, decesul nemaifiind direct prin boala renală','Excepții reversibile: înlăturarea obstrucției, imunosupresie în GN/vasculite, tratamentul HTA accelerate, corecția stenozelor critice de artere renale','Cauze geografice: malaria (GN în Africa sub-sahariană) și schistosomiaza obstructivă (Orientul Mijlociu, sudul Irakului)','Stadiile 1–3 progresează inevitabil spre dializă în sub 3 luni, fără excepții reversibile'],'ABCD',1392,'Boala cronică de rinichi — Definiție, reversibilitate și geografie',
 'Fixarea pragului >3 luni, a stabilității stadiilor 1–3 și a celor patru excepții reversibile, plus cauzele geografice.',
 ['Pragul >3 luni este din text.','Stadiile 1-3 de obicei nu se deteriorează continuu.','Cele patru excepții reversibile sunt listate.','Malaria și schistosomiaza sunt exemplele geografice.','Textul subliniază tocmai că multe stadii 1-3 nu progresează și că există excepții reversibile.']],
 8,'Intuiția „BCR = dializă inevitabilă” este infirmată de stabilitatea stadiilor 1–3 și de lista de cauze reversibile.',['>3 luni','schistosomiaza'],[1393]),

q(106,['Un pacient cu anemie a BCR începe epoetină-α. Doza inițială citată și monitorizarea sunt:',
 ['Darbepoetină 300 µg zilnic, fără control al tensiunii','Epoetină-α 50 U/kg de trei ori pe săptămână, sau darbepoetină 30 µg o dată pe săptămână; Hb la 2 săptămâni, țintă 100–120 g/L','Fier doar pe cale orală, ținta Hb >140 g/L','Transfuzii lunare, ASE fiind retrase din uz','Doza de 50 U/kg se dă o dată pe an, fără monitorizarea tensiunii'],'B',1394,'Boala cronică de rinichi — ASE: doze de start și ținta Hb',
 'Reținerea schemei epoetină 50 U/kg ×3/săptămână versus darbepoetină 30 µg/săptămână și a țintei 100–120 g/L.',
 ['Darbepoetina de start nu este 300 µg zilnic.','Textul dă 50 U/kg ×3/săptămână sau 30 µg/săptămână, cu Hb la 2 săptămâni.','Fierul i.v. este preferat; ținta >120 g/L nu a arătat beneficii în predializă.','ASE au modificat tratamentul; transfuziile se evită și pentru HLA.','Doza este de trei ori pe săptămână, nu anual.']],
 8,'Permutează 50 U/kg, 30 µg și 300 U/kg (doza de „non-responder”) între schemele de start.',['50 U/kg','30 µg o dată pe săptămână']),

q(107,['Complicații și perspective în tratamentul anemiei din BCR:',
 ['Hipertensiunea este un efect secundar important la 30% dintre pacienții la care se inițiază ASE','Aplazia eritrocitară pură mediată de anticorpi anti-eritropoietină a fost legată de garnitura de cauciuc a seringilor preumplute cu epoetină-α s.c.','Agenții orali care inhibă prolilhidroxilaza prelungesc viața HIF-1α, stimulând producția endogenă de eritropoietină','Corecția anemiei evită sensibilizarea HLA prin reducerea transfuziilor','ASE nu cresc tensiunea, aplazia fiind o complicație a fierului oral'],'ABCD',1394,'Boala cronică de rinichi — ASE: HTA 30%, PRCA, HIF',
 'Legarea cotei de 30% HTA, a PRCA de seringile preumplute și a clasei inhibitorilor de prolilhidroxilază.',
 ['Cota de 30% este explicită, cu monitorizare 6 luni.','Mecanismul garnitură-cauciuc/vehicul este descris.','Inhibitorii de prolilhidroxilază/HIF-1α sunt agenți promițători.','Evitarea transfuziilor reduce sensibilizarea HLA.','HTA este efect secundar important; PRCA ține de ASE s.c., nu de fierul oral.']],
 8,'PRCA prin garnitura seringii este un detaliu ușor de atribuit fierului; cota 30% HTA trebuie ținută minte.',['30% din pacienţii','prolilhidroxilaza']),

q(108,['Principiile hemodializei, dincolo de URR >65%:',
 ['Sângele anticoagulat este pompat printr-o membrană semipermeabilă; dializantul ultra-pur curge în contracurent','Moleculele mici traversează membrana prin difuziune; presiunea transmembranară permite ultrafiltrare și convecție','Pe o ședință standard de 4 ore pot fi circulați până la 80 de litri de sânge (~300 ml/min), echivalent RFG doar 10–12 ml/min pe m²','Inițierea precoce nu s-a asociat, în unele trialuri, cu ameliorarea supraviețuirii','O ședință de 4 ore oferă un clearance identic rinichiului nativ, RFG echivalentă 80 ml/min'],'ABCD',1399,'Boala cronică de rinichi — Hemodializa: contracurent, 80 L, RFG echivalentă',
 'Contrastul dintre volumul circulat (80 L) și RFG echivalentă modestă (10–12 ml/min), plus mesajul trialurilor de inițiere precoce.',
 ['Circuitul extracorporeal și contracurentul sunt din text.','Difuziunea și ultrafiltrarea/convecția sunt distinse.','80 L în 4 ore și RFG 10-12 ml/min pe m² sunt explicite.','Inițierea precoce fără beneficiu de supraviețuire este citată.','RFG echivalentă este 10-12, nu 80 ml/min; 80 este volumul circulat.']],
 8,'Permutează 80 L (volum circulat) cu 10–12 ml/min (RFG echivalentă), capcana aritmetică a paginii.',['80 de litri de sânge','10-12 ml/min pe m2']),

q(109,['Abordul vascular pentru hemodializă:',
 ['O dializă eficientă cere debit 250–450 mL/min, obținut prin FAV (arteră radială sau brahială și venă cefalică)','La capital venos deficitar sau arteriopatie (ex. diabet) se pot folosi proteze vasculare sintetice','Venipunctura de rutină pe venele destinate fistulei trebuie evitată','FAV se creează din timp, când creatinina este circa 400–500 µmol/L, pe brațul nedominant','Cateterul femoral de unică folosință înlocuiește FAV ca abord definitiv de elecție'],'ABCD',1399,'Boala cronică de rinichi — FAV: debit, materiale, timing',
 'Reținerea debitului 250–450 mL/min, a perechii radială/cefalică și a momentului de creare la creatinină 400–500.',
 ['Debitul și anatomia FAV sunt din textul despre hemodializă.','Protezele sintetice sunt alternativa la diabetici/capital venos sărac.','Evitarea venipuncturii figurează la pregătirea abordului.','Cifrele 400-500 µmol/L sunt din organizarea BRT.','FAV rămâne abordul de elecție, nu cateterul femoral definitiv.']],
 8,'Debitul 250–450 și creatinina 400–500 sunt ușor de permutat; distractorul promovează cateterul ca elecție.',['250 şi 450 mL/min','vena cefalică'],[1398]),

q(110,['Genetica și ciliopatia din BPRAD, dincolo de localizarea PKD1/PKD2:',
 ['PKD1 codifică policistina (interacțiuni celulă-celulă și celulă-matrix); PKD2, policistina 2 (canal de calciu)','Complexul de policistine din cili detectează fluxul tubular; perturbarea scade calciul citoplasmatic și duce la chisturi în celulele principale ale ductului colector','Asocierea cu boala polichistică hepatică se datorează mutațiilor GANAB (subunitatea α a glucozidazei II)','Forma autozomal recesivă ține de PKHD1 pe 6p21.1-p12, cel mai frecvent letală la vârste mici','PKD2 codifică un lanț COL4A5, identic sindromului Alport'],'ABCD',1405,'Bolile renale chistice — Policistine, cili și GANAB',
 'Legarea cililor/policistinelor de GANAB hepatic și deosebirea de PKHD1 recesiv.',
 ['Funcțiile celor două policistine sunt distinse.','Calea ciliară și ductul colector sunt explicite.','GANAB/GIia este necesară maturării PKD1/PKD2 la cili.','PKHD1 pe 6p definește forma recesivă letală precoce.','COL4A5 aparține Alport, nu PKD2.']],
 8,'Trei locusuri (PKD1, PKD2, PKHD1, GANAB) sunt concepute să fie amestecate cu COL4A5.',['GANAB','policistina 2']),

q(111,['Infecțiile intrachistice din BPRAD se tratează cel mai eficient cu:',
 ['Penicilină G, care nu penetrează peretele chistului','Aminoglicozide în monoterapie, inactive pe Gram-negativi','Nitrofurantoin, concentrat doar în vezică','Vancomicină, rezervată cocilor Gram-pozitivi de perete','Antibiotice lipofile active pe Gram-negativi, precum co-trimoxazolul și fluorochinolonele'],'E',1405,'Bolile renale chistice — BPRAD: infecția de chist',
 'Alegerea clasei lipofile (co-trimoxazol, fluorochinolone) care penetrează peretele chistului.',
 ['Penicilina G nu este agentul citat pentru penetrarea peretelui.','Aminoglicozidele nu sunt perechea lipofilă din text.','Nitrofurantoinul nu figurează.','Vancomicina nu este exemplul de antibiotic lipofil anti-Gram-negativ.','Textul cere antibiotice lipofile care penetrează peretele, active pe Gram-negativi: co-trimoxazol și fluorochinolone.']],
 8,'Penetrarea peretelui chistului selectează lipofilele; distractorii sunt antibiotice uzuale de ITU joasă.',['co-trimoxazolul','fluorochinolonele']),

q(112,['Epidemiologia BPRAD și dinamica chisturilor:',
 ['Este cea mai frecventă nefropatie ereditară, cu prevalență 1:400–1:1.000 la populația albă','Reprezintă nefropatia de bază la 3–10% dintre pacienții care intră în dializă cronică în Occident','Declinul RFG depinde de rata de creștere a chisturilor; cei cu creștere rapidă la RMN pierd funcția mai repede','Roscovitina (inhibitor CDK) și sirolimusul (mTOR) sunt menționate, alături de vaptani, pe modele animale','Prevalența este 1 la 2 milioane, identică bolii anti-MBG, fără nicio manifestare extra-renală'],'ABCD',1405,'Bolile renale chistice — BPRAD: 1:400–1:1000 și terapii experimentale',
 'Fixarea prevalenței 1:400–1:1000, a cotei 3–10% din dializă și a strategiilor anti-AMPc/mTOR/CDK.',
 ['Prevalența 1:400-1:1000 este explicită.','Cota 3-10% din programul de dializă este citată.','RMN-ul care arată creștere rapidă prezice declin mai accelerat.','Roscovitina și sirolimusul completează vaptanii.','1 la 2 milioane este incidența anti-MBG, nu a BPRAD.']],
 8,'Permutează 1:400–1:1000 cu 1 la 2 milioane (Goodpasture); roscovitina/sirolimusul sunt detalii nefolosite.',['1:400 şi 1:1.000','roscovitina']),

q(113,['Chisturile renale dobândite ale pacientului cu BRT:',
 ['Degenerarea chistică apare de regulă în rinichii nefuncționali tratați prin dializă sau transplant','Aceste chisturi dobândite au potențial de malignizare','Ocazional, chisturile simple mari produc durere și/sau hematurie prin sângerare intrachistică','Sunt identice BPRAD genetică și impun screeningul anevrismelor la toți dializații peste 30 de ani','Nu au potențial malign, spre deosebire de chisturile simple ale vârstnicului'],'ABC',1405,'Bolile renale chistice — Boala chistică dobândită și malignizare',
 'Separarea potențialului malign al chisturilor dobândite de dializă de chisturile simple ale vârstnicului.',
 ['Apariția pe rinichi nefuncționali dializați/transplantați este din text.','Potențialul de malignizare este explicit.','Durerea/hematuria prin sângerare intrachistică sunt menționate la chisturile simple mari.','Nu echivalează BPRAD și nu impun screening de anevrism „la toți dializații”.','Relația de malignitate este inversă: dobânditele au potențial, simplele vârstnicului de obicei nu.']],
 8,'Potențialul malign al chisturilor de dializă este contraintuitiv față de chisturile simple „de vârstă”.',['potenţial de malignizare','sângerare intrachistică']),

q(114,['Cadranul 36.27 (cauze comune de NTI acută) include, pe lângă peniciline, AINS și IPP:',
 ['Antibiotice: cefalosporine, ciprofloxacină, eritromicină, rifampicină, sulfonamide','Diuretice: furosemid, tiazide','Altele: alopurinol, carbamazepină, cimetidină, fenitoină, valproat','NTIU ~5% și boli inflamatorii sistemice (LES ~2%, nefropatia IgG4)','Cauza dominantă este Hantavirusul (~70%), medicamentele fiind rare sub 5%'],'ABCD',1385,'Nefritele tubulointerstițiale — Cadranul 36.27: lista extinsă de medicamente',
 'Completarea listei de medicamente (diuretice, anticonvulsivante, alopurinol) și a cotelor NTIU/LES, fără a inversa ierarhia 70% medicamentos.',
 ['Antibioticele enumerate completează penicilinele deja consacrate.','Furosemidul și tiazidele figurează la diuretice.','Alopurinolul, carbamazepina, cimetidina, fenitoina și valproatul sunt la „altele”.','NTIU 5% și LES 2% sunt în cadran.','Medicamentele sunt ~70%, nu Hantavirusul.']],
 8,'Inversează ierarhia 70% medicamentos versus 15% infecțios; lista de anticonvulsivante este detaliul nefolosit.',['carbamazepina','valproat']),
];
